window.__FACTOUR={"国立感染症研究所":{"s":"常設の見学はなし","t":["この庁舎(戸山)では、一般向けの見学ツアーは確認できませんでした。","武蔵村山市の村山庁舎では、過去にBSL4施設の見学会(2019年)や、年1回の一般公開(2022年は現地開催を中止)がありました。"],"u":"https://www.city.musashimurayama.lg.jp/shisei/torikumi/kansen/1015984/1002403/1010207.html","q":"村山庁舎 業務管理課 042-561-0771","c":"2026-10-15"},"国立国際医療研究所":{"s":"一般向けは確認できず","t":["一般向けの見学ツアーは確認できませんでした。","研修医・看護学生向けの病院見学会はあります(法人名は国立健康危機管理研究機構)。"],"u":"https://hosp.ncgm.go.jp/","q":"","c":"2026-10-15"},"情報通信研究機構(小金井本部)":{"s":"年1回の一般公開(過去実績)","t":["毎年夏に、施設の一般公開が行われてきました(小金井本部は7月下旬の2日間・無料)。","常設の展示施設の案内ページがあります。最新の日程は公式で確認してください。"],"u":"https://www.nict.go.jp/publicity/exhibition/","q":"","c":"2026-10-15"},"産業技術総合研究所 東京本部":{"s":"一般向けは確認できず","t":["東京本部(霞が関)での一般向けの見学ツアーは確認できませんでした。見学は、主につくば本部で行われています。"],"u":"https://www.aist.go.jp/","q":"","c":"2026-10-15"},"国立情報学研究所":{"s":"年1回のオープンハウス","t":["定期的な施設見学ツアーは確認できませんでした。","年1回の一般公開「オープンハウス」があります(2025年は6月20日、学術総合センター・無料・事前申込)。"],"u":"https://www.nii.ac.jp/","q":"","c":"2026-10-15"},"国立教育政策研究所":{"s":"見学ツアーは確認できず","t":["見学ツアーは確認できませんでした。","教育図書館は、入館に来館予約が必要です。"],"u":"https://www.nier.go.jp/","q":"","c":"2026-10-15"},"国立公文書館 アジア歴史資料センター":{"s":"ツアーあり(毎月・予約不要)","t":["「ふらっとツアー」: 東京本館で毎月1回、約1時間のバックヤード見学。事前申込不要・定員15名。開始15分前から、本館1階で受付。","親子・学生・教員向けの事前申込制ツアーや、団体見学もあります。開催日は、公式の予約カレンダーで確認できます。"],"u":"https://www.archives.go.jp/about/activity/application_tour.html","q":"見学の問い合わせ kengaku@archives.go.jp","c":"2026-10-15"},"宇宙航空研究開発機構 (JAXA)":{"s":"一般公開(年1回)・団体見学","t":["調布航空宇宙センター: 一般公開は年1回(2026年は4月19日・完全事前申込の抽選制)。","団体見学(ガイド付き・約90分)は、見学希望日の3週間前までにWebで申込み。展示室は、事前予約不要と案内されています(要確認)。"],"u":"https://fanfun.jaxa.jp/visit/chofu/","q":"","c":"2026-10-15"},"調布航空宇宙センター飛行場分室 (JAXA)":{"s":"一般公開(年1回)・団体見学","t":["調布航空宇宙センター: 一般公開は年1回(2026年は4月19日・完全事前申込の抽選制)。","団体見学(ガイド付き・約90分)は、見学希望日の3週間前までにWebで申込み。展示室は、事前予約不要と案内されています(要確認)。"],"u":"https://fanfun.jaxa.jp/visit/chofu/","q":"","c":"2026-10-15"},"東京文化財研究所":{"s":"団体のみ(個人は不可)","t":["施設見学は団体のみ。見学希望日の1か月以上前に、申請書の提出が必要です(個人の申込みは受理されません)。","資料閲覧室は外部の方も利用できます(月・水・金 10:00〜17:00、初回は利用者登録)。"],"u":"https://www.tobunken.go.jp/info/visit/visit.pdf","q":"","c":"2026-10-15"},"国立天文台三鷹キャンパス":{"s":"見学可(無料)・一部は要予約","t":["三鷹キャンパスは入場無料(10:00〜17:00・最終入場16:30)。正門で受付をして、敷地内の公開施設を見学できます。","4D2Uドームシアターや定例観望会(2026年は原則奇数月)は、事前申込制です。団体向けのガイド付き見学もあります。"],"u":"https://www.nao.ac.jp/access/mitaka/","q":"","c":"2026-10-15"},"国立がん研究センター":{"s":"常設の見学ツアーは確認できず","t":["築地キャンパスでの常設の見学ツアーは確認できませんでした。","がん対策研究所のオープンキャンパスなど、不定期の公開イベントがあります。"],"u":"https://www.ncc.go.jp/jp/icc/about/open_campus/2025/report/index.html","q":"","c":"2026-10-15"},"国立国語研究所":{"s":"年1回の一般公開(見学ツアーを含むことあり)","t":["年1回、建物を一般公開(2026年は7月4日「ニホンゴ探検2026」・無料)。","過去の公開では、研究図書室の見学ツアーがありました。"],"u":"https://www.ninjal.ac.jp/","q":"広報室 042-540-4539","c":"2026-10-15"}};
